css:
.thornsim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #20303f;
    background: linear-gradient(180deg, #eef2f6 0%, #e3e9ef 100%);
    border-radius: 16px;
}

.thornsim-container * {
    box-sizing: border-box;
}

.thornsim-header {
    position: relative;
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1f3346 0%, #2c4863 55%, #3a4a52 100%);
    color: #f4f8fb;
    border-radius: 14px;
    margin-bottom: 20px;
    border-bottom: 5px solid #e8a33d;
    box-shadow: 0 10px 26px rgba(31, 51, 70, 0.30);
    overflow: hidden;
}

.thornsim-header::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: repeating-linear-gradient(45deg, rgba(232,163,61,0.06) 0 14px, transparent 14px 28px);
    pointer-events: none;
}

.thornsim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.25rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
    position: relative;
}

.thornsim-header-tag {
    display: inline-block;
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f6c474;
    background: rgba(232, 163, 61, 0.16);
    border: 1px solid rgba(232, 163, 61, 0.45);
    padding: 5px 14px;
    border-radius: 4px;
    position: relative;
}

.thornsim-subtitle {
    margin: 0 auto;
    max-width: 820px;
    font-size: 0.98rem;
    line-height: 1.55;
    color: #cdd9e4;
    position: relative;
}

.thornsim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.95rem;
    font-weight: 600;
    color: #4a5e70;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.thornsim-period-counter #currentDay,
.thornsim-period-counter #maxPeriods {
    font-weight: 800;
    color: #c47f1c;
}

.thornsim-round-name {
    background: #2c4863;
    color: #f6c474;
    padding: 3px 12px;
    border-radius: 4px;
    font-size: 0.8rem;
    font-weight: 700;
    margin-left: 4px;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.thornsim-clock {
    margin-left: auto;
    font-size: 0.8rem;
    font-weight: 700;
    color: #b23b2e;
    background: rgba(178, 59, 46, 0.10);
    border: 1px solid rgba(178, 59, 46, 0.30);
    padding: 4px 12px;
    border-radius: 4px;
}

.thornsim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.thornsim-status-card {
    background: #ffffff;
    border-radius: 10px;
    padding: 16px 16px 14px;
    border: 1px solid #d3dde6;
    box-shadow: 0 4px 12px rgba(31, 51, 70, 0.08);
    border-left: 5px solid #6b7c8c;
}

.thornsim-card-rev { border-left-color: #2e8b57; }
.thornsim-card-adopt { border-left-color: #2c6fb0; }
.thornsim-card-cap { border-left-color: #8155b8; }
.thornsim-card-risk { border-left-color: #e8a33d; }

.thornsim-label {
    font-size: 0.73rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6b7c8c;
}

.thornsim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1f3346;
    font-variant-numeric: tabular-nums;
}

.thornsim-card-rev .thornsim-value { color: #2e8b57; }
.thornsim-card-adopt .thornsim-value { color: #2c6fb0; }
.thornsim-card-cap .thornsim-value { color: #8155b8; }
.thornsim-card-risk .thornsim-value { color: #c47f1c; }

.thornsim-sublabel {
    font-size: 0.75rem;
    color: #7a8a99;
    line-height: 1.35;
}

.thornsim-rev-negative .thornsim-value { color: #b23b2e; }
.thornsim-rev-positive .thornsim-value { color: #2e8b57; }

.thornsim-risk-high { border-left-color: #b23b2e; }
.thornsim-risk-high .thornsim-value { color: #b23b2e; }
.thornsim-risk-low { border-left-color: #2e8b57; }
.thornsim-risk-low .thornsim-value { color: #2e8b57; }

.thornsim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1f3346;
    color: #e8eef4;
    padding: 11px 18px;
    border-radius: 8px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border-left: 5px solid #e8a33d;
}

.thornsim-budget-bar #budgetDisplay {
    font-size: 1.08rem;
    letter-spacing: 0.3px;
    color: #f6c474;
}

.thornsim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #e8a33d;
    border-radius: 10px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 12px rgba(31, 51, 70, 0.08);
}

.thornsim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.thornsim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1f3346;
    margin-bottom: 6px;
}

.thornsim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #3a4d5e;
}

.thornsim-briefing-text strong { color: #c47f1c; }
.thornsim-briefing-text em { color: #b23b2e; font-style: italic; }

.thornsim-controls {
    background: #ffffff;
    border-radius: 12px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d3dde6;
    box-shadow: 0 4px 12px rgba(31, 51, 70, 0.08);
}

.thornsim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1f3346;
    border-bottom: 2px solid #e8a33d;
    padding-bottom: 8px;
}

.thornsim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2c4863;
    margin: 14px 0 6px;
}

.thornsim-container select,
.thornsim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #b9c6d2;
    border-radius: 7px;
    font-size: 0.92rem;
    background-color: #f7fafc;
    color: #20303f;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.thornsim-container select:focus,
.thornsim-container input[type="number"]:focus {
    outline: none;
    border-color: #e8a33d;
    box-shadow: 0 0 0 3px rgba(232, 163, 61, 0.20);
}

.thornsim-container select option {
    background-color: #ffffff;
    color: #20303f;
}

.thornsim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #e8a33d;
}

.thornsim-range-readout,
.thornsim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #4a5e70;
    margin-top: 4px;
}

.thornsim-range-readout span:nth-child(2),
.thornsim-alloc-readout span:nth-child(2) {
    color: #c47f1c;
    font-weight: 800;
}

.thornsim-hint {
    font-size: 0.8rem;
    color: #7a8a99;
    margin-top: 4px;
    line-height: 1.4;
}

.thornsim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.thornsim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f4f7fa;
    border: 1px solid #d8e0e8;
    border-radius: 7px;
    padding: 8px 12px;
}

.thornsim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2c4863;
}

.thornsim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.thornsim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.thornsim-container .btn-primary {
    background: linear-gradient(135deg, #c47f1c 0%, #e8a33d 100%);
    border: none;
    color: #2a1c05;
    padding: 11px 26px;
    border-radius: 7px;
    box-shadow: 0 6px 16px rgba(196, 127, 28, 0.35);
}

.thornsim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.thornsim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #b9c6d2;
    color: #4a5e70;
    background: transparent;
}

.thornsim-coach {
    background: linear-gradient(135deg, #243a4f 0%, #2c4863 100%);
    color: #dde7f0;
    border-radius: 12px;
    padding: 16px 20px;
    margin-bottom: 18px;
    border-left: 5px solid #b23b2e;
    box-shadow: 0 4px 12px rgba(31, 51, 70, 0.18);
}

.thornsim-coach-header {
    font-size: 0.77rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #f6c474;
    margin-bottom: 8px;
}

.thornsim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.thornsim-coach-body strong { color: #f6c474; }
.thornsim-coach-body em { color: #f0a3a3; font-style: italic; }

.thornsim-history,
.thornsim-chart {
    background: #ffffff;
    border-radius: 12px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d3dde6;
    box-shadow: 0 4px 12px rgba(31, 51, 70, 0.08);
}

.thornsim-history h3,
.thornsim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1f3346;
}

.thornsim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2c4863;
}

.thornsim-container table#usfHistoryTable th {
    background: #1f3346;
    color: #f6c474;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.71rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e8a33d;
}

.thornsim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #e1e8ee;
    color: #3a4d5e;
}

.thornsim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f4f7fa;
}

.thornsim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .thornsim-container {
        padding: 14px;
    }
    .thornsim-header h1 {
        font-size: 1.7rem;
    }
    .thornsim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .thornsim-value {
        font-size: 2rem;
    }
    .thornsim-clock {
        margin-left: 0;
    }
    .thornsim-period-counter {
        font-size: 0.88rem;
    }
    .thornsim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .thornsim-alloc-row {
        flex-wrap: wrap;
    }
    .thornsim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .thornsim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}



/* \u2500\u2500 v1.1.0 completion scorecard (append-only, namespaced .thorn-cm-*, Thornbury navy/blue/amber) \u2500\u2500 */
.thorn-cm { margin-top: 8px; }
.thorn-cm-incomplete { text-align: center; color: #4a5b6b; font-size: 1rem; padding: 18px; }
.thorn-cm-head { display: flex; flex-wrap: wrap; gap: 16px; align-items: stretch; margin-bottom: 18px; }
.thorn-cm-score { flex: 0 0 auto; min-width: 150px; background: linear-gradient(135deg, #1f3346 0%, #2c6fb0 58%, #c47f1c 135%); color: #ffffff; border-radius: 14px; padding: 16px 22px; text-align: center; box-shadow: 0 8px 22px rgba(31, 51, 70, 0.28); }
.thorn-cm-score-num { font-size: 2.9rem; font-weight: 800; line-height: 1; }
.thorn-cm-score-den { font-size: 1.1rem; font-weight: 600; opacity: 0.85; }
.thorn-cm-score-lbl { margin-top: 6px; font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #f0c987; }
.thorn-cm-verdict { flex: 1 1 220px; display: flex; flex-direction: column; justify-content: center; background: #ffffff; border: 1px solid #d7e0ea; border-left: 5px solid #2c6fb0; border-radius: 14px; padding: 16px 20px; }
.thorn-cm-verdict-lbl { font-size: 0.72rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #5a6b7b; }
.thorn-cm-verdict-tier { margin-top: 4px; font-size: 1.5rem; font-weight: 800; color: #1f3346; line-height: 1.15; }
.thorn-cm-section { margin-bottom: 16px; }
.thorn-cm-section-h { font-size: 0.75rem; text-transform: uppercase; letter-spacing: 1px; font-weight: 700; color: #5a6b7b; margin-bottom: 8px; }
.thorn-cm-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.thorn-cm-chip { display: inline-flex; align-items: center; gap: 6px; font-size: 0.85rem; font-weight: 600; padding: 6px 12px; border-radius: 999px; border: 1px solid transparent; }
.thorn-cm-ok { background: rgba(31, 157, 85, 0.14); color: #1f9d55; border-color: rgba(31, 157, 85, 0.42); }
.thorn-cm-no { background: rgba(214, 69, 69, 0.12); color: #d64545; border-color: rgba(214, 69, 69, 0.42); }
.thorn-cm-ico { font-weight: 800; }
.thorn-cm-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(140px, 1fr)); gap: 12px; }
.thorn-cm-kpi { background: #ffffff; border: 1px solid #d7e0ea; border-top: 4px solid #c47f1c; border-radius: 12px; padding: 14px 12px; text-align: center; }
.thorn-cm-kpi-val { font-size: 1.6rem; font-weight: 800; color: #1f3346; line-height: 1; }
.thorn-cm-kpi-lbl { margin-top: 6px; font-size: 0.82rem; font-weight: 700; color: #1f2a36; }
.thorn-cm-kpi-sub { margin-top: 2px; font-size: 0.7rem; color: #5a6b7b; }
.thorn-cm-insights { margin: 0; padding-left: 18px; color: #1f2a36; }
.thorn-cm-insights li { margin: 4px 0; font-size: 0.92rem; line-height: 1.45; }
@media (max-width: 560px) { .thorn-cm-head { flex-direction: column; } .thorn-cm-score { min-width: 0; } }
.thornsim-container select:focus-visible, .thornsim-container input:focus-visible, .thornsim-container button:focus-visible { outline: 3px solid #f5a623; outline-offset: 2px; }
@media (prefers-reduced-motion: reduce) { .thornsim-container, .thornsim-container * { transition: none !important; animation: none !important; scroll-behavior: auto !important; } }

