        getChartData(state) {
            const ds = (state && state.domainState) || {};
            const labels = (ds.adoptionHistory || []).map((_, i) => (i === 0 ? window.mySimulation.t(`chart_start`) : `R` + i));
            return {
                thornChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.adoptionHistory || [] },
                        { data: ds.capabilityHistory || [] },
                        { data: ds.riskHistory || [] }
                    ]
                }
            };
        }

        _composite(ds) {
            const clamp = function(v) { return Math.max(0, Math.min(100, v)); };
            const retained = ds.retained;
            const adoption = Math.round(ds.adoption);
            const capability = Math.round(ds.capability);
            const risk = Math.round(ds.risk);
            // Adoption and capability are scored against what a coordinated programme can reach in the period (about 62), not against 100.
            let c = clamp((retained / this.EXPOSED) * 100) * 0.34 + clamp(adoption * 100 / 62) * 0.24 + clamp(capability * 100 / 62) * 0.20 + (100 - risk) * 0.22;
            const failed = ds.techStranded || ds.bigAccountLost || ds.pricewar;
            const delivered = !failed && !ds.incentiveKept && !ds.allDigital && retained >= 12 && adoption >= 35 && capability >= 55;
            if (!delivered) c = Math.min(c, 84);
            if (failed) c = Math.min(c, 69);
            return Math.round(c);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const retained = ds.retained;
            const adoption = Math.round(ds.adoption);
            const capability = Math.round(ds.capability);
            const risk = Math.round(ds.risk);

            // Composite extracted to _composite() so the persisted per-period score and this
            // completion summary are identical by construction (v1.1.0).
            const composite = this._composite(ds);

            const defended = retained >= 12 && !ds.bigAccountLost;
            const adopted = adoption >= 35;
            const capable = capability >= 55;
            const failed = ds.techStranded || ds.bigAccountLost || ds.pricewar || risk >= 70;

            // v1.1.0 — tier labels moved to i18n keys (were hardcoded English).
            let tierKey = "grade_stalled";
            if (ds.techStranded) tierKey = "grade_stranded";
            else if (ds.bigAccountLost) tierKey = "grade_accountlost";
            else if (ds.pricewar) tierKey = "grade_pricewar";
            else if (composite >= 85) tierKey = "grade_delivered";
            else if (defended && capable && composite >= 70) tierKey = "grade_mandatemet";
            else if (composite >= 62) tierKey = "grade_mixed";
            const performance = window.mySimulation.t(tierKey);

            const insights = [];
            const g1 = (history[1] && history[1].decisions) || {}, g2 = (history[2] && history[2].decisions) || {};
            const cleanRun = g1.phase === "platformfirst" && g1.reskill >= 1.0 && g2.coverage === "valuebased" && g2.commission === "neutral" && g2.governance === "pricefloor";
            if (tierKey === "grade_delivered") insights.push(window.mySimulation.t(cleanRun ? "insight_delivered" : "insight_strong"));
            else if (ds.techStranded) insights.push(window.mySimulation.t(`insight_stranded`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.bigAccountLost) insights.push(window.mySimulation.t(`insight_account`));
            if (ds.pricewar) insights.push(window.mySimulation.t(`insight_pricewar`));
            if (capability < 45) insights.push(window.mySimulation.t(`insight_capability`));
            if (adoption < 25) insights.push(window.mySimulation.t(`insight_adoption`));
            if (defended && risk <= 30) insights.push(window.mySimulation.t(`insight_governed`));

            const T = function(k) { return window.mySimulation.t(k); };
            const hd = function(i) { return (history[i] && history[i].decisions) || {}; };
            const named = [];
            if (history.length >= 3 && hd(2).coverage === "alldigital") named.push(T("insight_alldigital"));
            if (history.length >= 3 && hd(2).commission === "unchanged") named.push(T("insight_commission"));
            let prevC = this._composite({ retained: 0, adoption: this.START_ADOPTION, capability: this.START_CAP, risk: this.START_RISK }), turn = 0, turnD = 0;
            for (let i = 0; i < history.length; i++) {
                const hp = history[i].domainState && history[i].domainState.performance;
                if (!hp || typeof hp.overallScore !== "number") continue;
                const dl = Math.abs(hp.overallScore - prevC);
                if (dl > turnD) { turnD = dl; turn = i + 1; }
                prevC = hp.overallScore;
            }
            const turnArr = (turn >= 1 && turn <= 4 && turnD >= 3) ? [T("turn_r" + turn)] : [];
            const dqs = (history.length >= this.ROUNDS.length) ? [T("dq_1"), T("dq_2")] : [];
            const allInsights = insights.slice(0, 1).concat(turnArr, named, insights.slice(1), dqs);
            return {
                retained: retained,
                adoption: adoption,
                capability: capability,
                risk: risk,
                defended: defended,
                adopted: adopted,
                capable: capable,
                failed: failed,
                composite: composite,
                overallScore: composite,
                totalScore: composite,
                score: composite,
                performance: tierKey,
                performanceLabel: performance,
                performanceKey: tierKey,
                tierKey: tierKey,
                insights: allInsights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k) => window.mySimulation.t(k);
            if (!summary || summary.composite == null) {
                return `<div class="thorn-cm"><p class="thorn-cm-incomplete">` + t(`cm_incomplete`) + `</p></div>`;
            }
            const s = summary;
            const chip = (ok, label) => `<span class="thorn-cm-chip ` + (ok ? `thorn-cm-ok` : `thorn-cm-no`) + `">` +
                `<span class="thorn-cm-ico">` + (ok ? `\u2713` : `\u2717`) + `</span>` + label + ` \u00b7 ` +
                (ok ? t(`cm_met`) : t(`cm_missed`)) + `</span>`;
            const kpi = (label, val, sub) => `<div class="thorn-cm-kpi"><div class="thorn-cm-kpi-val">` + val +
                `</div><div class="thorn-cm-kpi-lbl">` + label + `</div>` +
                (sub ? `<div class="thorn-cm-kpi-sub">` + sub + `</div>` : ``) + `</div>`;
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `` +
`<div class="thorn-cm">` +
  `<div class="thorn-cm-head">` +
    `<div class="thorn-cm-score"><div class="thorn-cm-score-num">` + Math.round(s.composite) +
       `<span class="thorn-cm-score-den">/100</span></div>` +
       `<div class="thorn-cm-score-lbl">` + t(`cm_score`) + `</div></div>` +
    `<div class="thorn-cm-verdict"><div class="thorn-cm-verdict-lbl">` + t(`cm_verdict`) + `</div>` +
       `<div class="thorn-cm-verdict-tier">` + (s.performanceLabel || t(s.tierKey)) + `</div></div>` +
  `</div>` +
  `<div class="thorn-cm-section"><div class="thorn-cm-section-h">` + t(`cm_targets`) + `</div>` +
    `<div class="thorn-cm-chips">` + chip(!!s.defended, t(`cm_t_defended`)) + chip(!!s.adopted, t(`cm_t_adopted`)) +
      chip(!!s.capable, t(`cm_t_capable`)) + chip(!s.failed, t(`cm_t_governed`)) + `</div></div>` +
  `<div class="thorn-cm-section"><div class="thorn-cm-section-h">` + t(`cm_kpis`) + `</div>` +
    `<div class="thorn-cm-kpis">` +
      kpi(t(`rev_label`), this._fmtMoney(Number(s.retained)), t(`cm_sub_retained`)) +
      kpi(t(`adopt_label`), Math.round(Number(s.adoption)) + `%`, t(`cm_sub_adoption`)) +
      kpi(t(`cap_label`), Math.round(s.capability), t(`cm_sub_capability`)) +
      kpi(t(`risk_label`), Math.round(s.risk), t(`cm_sub_risk`)) +
    `</div></div>` +
  (insights ? `<div class="thorn-cm-section"><div class="thorn-cm-section-h">` + t(`cm_insights`) +
      `</div><ul class="thorn-cm-insights">` + insights + `</ul></div>` : ``) +
`</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.techStranded) return window.mySimulation.t(`hint_stranded`);
            if (ds.pricewar) return window.mySimulation.t(`hint_pricewar`);
            if (ds.bigAccountLost) return window.mySimulation.t(`hint_account`);
            if (state.currentPeriod >= 3 && ds.adoption < 20) return window.mySimulation.t(`hint_adoption`);
            if (ds.risk >= 65) return window.mySimulation.t(`hint_risk`);
            if (ds.retained >= 15 && ds.adoption >= 35 && ds.risk <= 30) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            const self = this;
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.retained`, label: `Retained`, i18nKey: `col_retained`, formatter: (v) => self._fmtMoney(Number(v)) },
                { key: `results.adoption`, label: `Adoption`, i18nKey: `col_adoption`, formatter: (v) => Math.round(v) + `%` },
                { key: `results.capability`, label: `Capability`, i18nKey: `col_capability`, formatter: (v) => Math.round(v) },
                { key: `results.risk`, label: `Risk`, i18nKey: `col_risk`, formatter: (v) => Math.round(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const tt = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };
            const cvs = document.getElementById("thornChart");
            if (cvs) cvs.setAttribute("aria-label", tt("chart_heading"));
            if ((state.currentPeriod || 1) > this.ROUNDS.length) {
                const ft = document.getElementById("briefingTitle"); if (ft) ft.textContent = tt("final_title");
                const fx = document.getElementById("briefingText"); if (fx) fx.innerHTML = tt("final_text");
                const fn = document.getElementById("roundNameDisplay"); if (fn) fn.textContent = "";
                const fc = document.getElementById("clockDisplay"); if (fc) fc.textContent = "";
                for (let i = 0; i < this.ROUNDS.length; i++) { const pn = document.getElementById(this.ROUNDS[i].panelId); if (pn) pn.style.display = "none"; }
                return;
            }
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
